<?php require_once __DIR__.'/../includes/leave.php';require_login(['admin']);post_guard();
if($_SERVER['REQUEST_METHOD']==='POST'){$a=$_POST['do']??'';$id=(int)($_POST['id']??0);
 try{
  if($a==='save'){$n=trim($_POST['name']);$d=$_POST['start'];$e2=$_POST['end']?:null;if($n===''||!$d)throw new Exception('الاسم والتاريخ مطلوبان.');if($e2&&$e2<$d)throw new Exception('تاريخ النهاية قبل البداية.');
   if($id)$pdo->prepare('UPDATE holidays SET name=?,holiday_date=?,end_date=?,description=? WHERE id=?')->execute([$n,$d,$e2,trim($_POST['description']),$id]);else $pdo->prepare('INSERT INTO holidays(name,holiday_date,end_date,description) VALUES(?,?,?,?)')->execute([$n,$d,$e2,trim($_POST['description'])]);
   audit('holiday_save',"$n $d");flash('تم حفظ العطلة.');}
  if($a==='toggle'){$pdo->prepare('UPDATE holidays SET is_active=1-is_active WHERE id=?')->execute([$id]);audit('holiday_toggle',"#$id");flash('تم تحديث الحالة.');}
  if($a==='del'){$pdo->prepare('DELETE FROM holidays WHERE id=?')->execute([$id]);audit('holiday_delete',"#$id");flash('تم حذف العطلة.');}
 }catch(PDOException $x){flash('يوجد عطلة بنفس تاريخ البداية.','error');}catch(Exception $x){flash($x->getMessage(),'error');}
 header('Location: holidays.php');exit;}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM holidays WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
$rows=$pdo->query('SELECT * FROM holidays ORDER BY holiday_date DESC')->fetchAll();page_start('العطلات الرسمية');ph('العطلات الرسمية','عطلات المؤسسة التي تُستثنى من الحضور وحساب الإجازات','<a class="btn" href="holidays.php" data-modal="hm" data-title="إضافة عطلة" data-submit="إضافة عطلة" data-fill=\'{"id":0,"name":"","start":"","end":"","description":""}\'>'.ic('plus').'إضافة عطلة</a>');
$hs=$pdo->query("SELECT COUNT(*) t,SUM(is_active=1 AND COALESCE(end_date,holiday_date)>=CURDATE()) up,SUM(is_active=1 AND DATE_FORMAT(holiday_date,'%Y-%m')=DATE_FORMAT(CURDATE(),'%Y-%m')) mo FROM holidays")->fetch();
echo kpis([[(int)$hs['t'],'إجمالي العطلات','','','flag'],[(int)$hs['up'],'عطلات قادمة','info','','calendar'],[(int)$hs['mo'],'عطلات هذا الشهر','','','calendar-check']]);
modal_open('hm',$edit?'تعديل عطلة':'إضافة عطلة',['form'=>'method="post"','wide'=>true,'grid'=>true,'desc'=>'اترك «إلى تاريخ» فارغًا لعطلة يوم واحد.']);?><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="do" value="save"><input type="hidden" name="id" value="<?=$edit['id']??0?>">
<label>اسم العطلة<input name="name" value="<?=e($edit['name']??'')?>" required></label><label>الوصف<input name="description" value="<?=e($edit['description']??'')?>"></label><label>من تاريخ<input type="date" name="start" value="<?=e($edit['holiday_date']??'')?>" required></label><label>إلى تاريخ (اختياري)<input type="date" name="end" value="<?=e($edit['end_date']??'')?>"></label>
<?php modal_close('<button class="btn">'.($edit?'تحديث':'إضافة عطلة').'</button><a class="btn ghost" href="holidays.php" data-close>إلغاء</a>',true);if($edit)echo '<script>window.addEventListener("load",()=>openModal("hm"))</script>';?>
<div class="card tbl"><table><tr><th>العطلة</th><th>من</th><th>إلى</th><th>الحالة</th><th></th></tr><?php foreach($rows as $r):?><tr><td class="cmain"><b><?=e($r['name'])?></b><?php if($r['description']):?><br><small><?=e($r['description'])?></small><?php endif;?></td><td><?=e($r['holiday_date'])?></td><td><?=e($r['end_date']?:'—')?></td><td><?=sb($r['is_active']?'active':'inactive',$r['is_active']?'مفعّلة':'معطّلة')?></td>
<td class="act"><a class="btn ghost sm" href="?edit=<?=$r['id']?>" data-modal="hm" data-title="تعديل عطلة" data-submit="تحديث" data-fill="<?=e(json_encode(['id'=>(int)$r['id'],'name'=>$r['name'],'start'=>$r['holiday_date'],'end'=>$r['end_date']??'','description'=>$r['description']??''],JSON_UNESCAPED_UNICODE))?>"><?=ic('pencil')?>تعديل</a><?php foreach([['toggle',$r['is_active']?'تعطيل':'تفعيل','ghost'],['del','حذف','danger']] as [$d,$t,$c]):?><form method="post" data-confirm="<?=$d==='del'?'سيُحذف هذا اليوم من قائمة العطلات الرسمية.':'يمكنك تغيير الحالة لاحقًا.'?>" data-confirm-title="<?=$t?> «<?=e($r['name'])?>»؟" data-confirm-ok="<?=$t?>" <?=$d==='del'?'data-confirm-tone="danger"':''?>><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="do" value="<?=$d?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn sm <?=$c?>"><?=$d==='del'?ic('trash'):''?><?=$t?></button></form><?php endforeach;?></td></tr>
<?php endforeach;if(!$rows)echo empty_row(5,'لا توجد عطلات','أضف العطلات الرسمية لاستثنائها من الحضور وحساب الإجازات.','flag');?></table></div><?php page_end();
